intentos.respuesta_cruda:
{
  "sql": "SELECT COUNT(DISTINCT v.seller_id) AS num_vendedores, SUM(v.ingresos) AS ingresos_totales FROM ( SELECT s.seller_id, SUM(oi.price) AS ingresos, AVG(rv.review_score) AS calificacion, SUM(CASE WHEN e.entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(e.order_id) AS pct_retrasos FROM sellers s JOIN order_items oi ON s.seller_id = oi.seller_id JOIN vw_pedidos_validos p ON oi.order_id = p.order_id LEFT JOIN order_reviews rv ON p.order_id = rv.order_id LEFT JOIN vw_entregas_retrasos e ON p.order_id = e.order_id GROUP BY s.seller_id HAVING COUNT(DISTINCT p.order_id) >= 30 ) v WHERE v.calificacion < 3.5 OR v.pct_retrasos >= 15"
}
